export const BODY: string = "\n<p>جدید ویب سائٹ سے ڈاؤن لوڈ شدہ AVIF تصویر اکثر اس ایپ میں کھلنے سے انکار کر دیتی ہے جس میں آپ کو چاہیے۔ اسے JPG میں بدلنے میں ایک منٹ سے کم لگتا ہے، اور نتیجہ ہر جگہ کام کرتا ہے۔</p>\n<p>صرف مشکل حصہ شفافیت ہے، اور صرف شرط یہ ہے کہ آپ کا براؤزر AVIF کو پہلے سے ڈی کوڈ کر سکے۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، تاکہ آپ کی پہلی تبدیلی صاف نکلے۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: اپنا براؤزر جانچیں</h2>\n<p>آپ کو جدید براؤزر چاہیے جو AVIF کو خود ڈی کوڈ کرے۔ کروم، ایج، فائر فاکس اور سفاری کے حالیہ نسخے سب ایسا کرتے ہیں، اس لیے اگر آپ کا پرانا ہو تو اسے اپ ڈیٹ کریں۔</p>\n<p>اپنے آلے پر AVIF فائلیں تلاش کریں۔ وہ عام طور پر ڈاؤن لوڈ سے آتی ہیں، جہاں ویب سائٹ نے بتائے بغیر JPG کی بجائے AVIF دے دیا تھا۔</p>\n<p>جانچیں کہ تصویروں میں شفافیت ہے یا نہیں۔ تصویروں میں عام طور پر نہیں ہوتی، جبکہ لوگو اور اسٹیکر میں ہو سکتی ہے، اور شفاف حصوں کو میٹ رنگ چاہیے ہوتا ہے۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: AVIF سے JPG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/avif-ko-jpg-mein-convert-karein/\">AVIF to JPG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ، میٹ رنگ چننے والا اور کوالٹی سلائیڈر دکھائی دے گا۔ یہ تین کنٹرول ہی پورا کام ہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو ذاتی تصویروں اور ڈاؤن لوڈ شدہ فائلوں کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی AVIF فائلیں اپ لوڈ کریں</h2>\n<p>اپنی AVIF فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ بیچ کے لیے کئی فائلیں ایک ساتھ چن سکتے ہیں۔</p>\n<p>ہر فائل کارڈ کے طور پر دکھائی دیتی ہے، تھمب نیل، ابعاد اور سائز کے ساتھ۔ فوری نظر سے یقین ہو جاتا ہے کہ درست فائلیں لوڈ ہوئیں اور کوئی اضافی نہیں آئی۔</p>\n<p>اگر کوئی فائل لوڈ نہ ہو تو آپ کا براؤزر AVIF ڈی کوڈ نہیں کر سکتا۔ براؤزر کو تازہ ترین نسخے پر اپ ڈیٹ کریں اور دوبارہ آزمائیں۔</p>\n<h2 id=\"step-3-matte-colour\">مرحلہ 3: میٹ رنگ چنیں</h2>\n<p>شفاف حصوں کے بھرنے کے لیے میٹ رنگ چننے والے پر کلک کریں۔ سفید پہلے سے طے شدہ ہے اور زیادہ تر استعمال کے لیے موزوں ہے۔</p>\n<p>گہرے ڈیزائن کے لیے کالا چنیں، یا کسی مخصوص ویب سائٹ پس منظر سے بالکل ملانے کے لیے ہیکس کوڈ لکھیں۔ ملا ہوا پس منظر لوگو کو وہاں کا حصہ دکھاتا ہے۔</p>\n<p>اگر آپ کی AVIF میں شفافیت نہیں ہے تو یہ ترتیب کچھ نہیں کرتی۔ تصویریں جو بھی رنگ چنیں، ویسے ہی گزر جاتی ہیں۔</p>\n<h2 id=\"step-4-quality\">مرحلہ 4: کوالٹی سلائیڈر طے کریں</h2>\n<p>زیادہ تر AVIF تصویروں کے لیے 85 فیصد JPG کوالٹی بہترین نقطہ ہے۔ تصویر صاف لگتی ہے، فائل معقول ہوتی ہے اور نقصان نظر نہیں آتا۔</p>\n<p>پرنٹ جانے والی تصویروں کے لیے 90 فیصد یا زیادہ استعمال کریں۔ پرنٹ وہ خامیاں دکھاتا ہے جو اسکرین چھپاتی ہے، اور ایک اہم تصویر کے لیے اضافی سائز سستا ہے۔</p>\n<p>سائز حد والے فارم جانے والی تصویروں کے لیے 85 سے شروع کریں اور آہستہ آہستہ نیچے جائیں۔ ہر مرحلے کے بعد سائز جانچیں، اور جیسے ہی فائل فٹ ہو جائے، رک جائیں۔</p>\n<h2 id=\"step-5-convert-preview\">مرحلہ 5: بدلیں اور نتیجہ کا پیش نظارہ دیکھیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ہر فائل الگ بدلتی ہے، اس لیے آپ پیش رفت کارڈ بہ کارڈ دیکھ سکتے ہیں۔</p>\n<p>ہر کارڈ پرانی AVIF سائز کے ساتھ نیا JPG سائز دکھاتا ہے۔ JPG بڑا ہونے کی توقع رکھیں، کیونکہ AVIF JPG سے زیادہ مؤثر ہے۔</p>\n<p>نتیجہ ساتھ ساتھ جانچنے کے لیے کسی کارڈ پر Compare پر کلک کریں۔ اسپلٹ ہینڈل تصویر پر گھسیٹیں اور چہرے، متن اور رنگ جانچیں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: JPG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ایک JPG محفوظ کرنے کے لیے کسی کارڈ پر Download پر کلک کریں۔ فائل نام آپ کا اصل نام .jpg ایکسٹینشن کے ساتھ رکھتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی JPG ہو۔ یہ ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں تیز ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ JPG اپنے فوٹو ویور میں کھولیں، یقین کریں کہ وہ درست لگتی ہے اور اس ایپ میں کھلتی ہے جسے اس کی ضرورت ہے۔</p>\n<ol>\n<li>AVIF سے JPG ٹول کھولیں اور اپنی AVIF فائلیں اپ لوڈ کریں۔</li>\n<li>شفاف حصوں کے لیے میٹ رنگ چنیں۔</li>\n<li>کوالٹی سلائیڈر 85 فیصد پر طے کریں۔</li>\n<li>بدلیں، Compare سے پیش نظارہ دیکھیں، پھر JPG ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-a-batch\">ایک ساتھ کئی AVIF ڈاؤن لوڈ بدلنا</h2>\n<p>فائل پکر میں کئی AVIF فائلیں ایک ساتھ چنیں۔ وہ سب قطار میں لوڈ ہو جاتی ہیں، اور ایک کلک سے سب JPG میں بدل جاتی ہیں۔</p>\n<p>پورے بیچ کے لیے ایک ہی میٹ رنگ اور کوالٹی استعمال کریں۔ مستقل مزاجی اہم ہے جب تصویریں ایک ہی پراجیکٹ یا دستاویز سے تعلق رکھتی ہوں۔</p>\n<p>بیچ چلتے ہوئے غلطی والے بیج دیکھیں۔ جو فائل آپ کا براؤزر ڈی کوڈ نہیں کر سکتا، وہ انتباہ دکھاتی ہے، اور براؤزر اپ ڈیٹ کرنے سے عام طور پر ٹھیک ہو جاتی ہے۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر تبدیلی ناکام ہو تو اپنا براؤزر اپ ڈیٹ کریں۔ AVIF ڈی کوڈ کرنے کے لیے حالیہ نسخہ چاہیے، اور پرانا براؤزر فائلیں بالکل نہیں پڑھ سکتا۔</p>\n<p>اگر JPG مدھم لگے تو تبدیلی کے دوران HDR یا وسیع رنگ بدل گئے ہوں گے۔ کسی بھی فوٹو ایپ میں ہلکی سیچوریشن ایڈجسٹمنٹ سے چمک واپس آ جاتی ہے۔</p>\n<p>اگر شفاف AVIF کو کالا ڈبہ مل جائے تو میٹ رنگ کالا تھا یا طے نہیں ہوا تھا۔ اسے سفید یا اپنے صفحے کے رنگ پر بدلیں اور دوبارہ بدلیں۔</p>\n<h2 id=\"after-converting\">بدلنے کے بعد: آگے کیا کریں</h2>\n<p>اگر JPG فارم کے لیے ہیں تو اپ لوڈ سے پہلے سائز حد جانچیں۔ 85 فیصد کوالٹی پر بدلی ہوئی JPG 2 MB حد سے اوپر ہو سکتی ہے، اور آپ کو اسے کمپریس کرنا پڑ سکتا ہے۔</p>\n<p>جب پورٹل بالکل سائز مانگے تو <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB کمپریسر</a> یا <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">Target File Size Compressor</a> استعمال کریں۔ پہلے بدلیں، پھر کمپریس کریں، اسی ترتیب میں۔</p>\n<p>اگر JPG ویب سائٹ کے لیے ہیں تو انہیں WebP میں بدلنے پر غور کریں۔ <a href=\"/ur/jpg-ko-webp-mein-convert-karein/\">JPG to WebP کنورٹر</a> آپ کی نئی JPG لے کر انہیں ویب کے لیے چھوٹا کر دیتا ہے۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور اپنے ڈاؤن لوڈ یا گیلری سے AVIF فائلیں چنیں۔ تبدیلی فون پر چلتی ہے، اور JPG آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی AVIF فائلیں موبائل پروسیسر پر ڈی کوڈ ہونے میں وقت لیتی ہیں۔ ایک وقت میں دس فائلیں آرام دہ ہیں۔</p>\n<p>ڈاؤن لوڈ آپ کے فون کے Downloads فولڈر میں آتے ہیں۔ آئی فون پر Files ایپ جانچیں، اینڈرائیڈ پر اپنا فائل مینیجر جانچیں۔</p>\n<h2 id=\"avif-for-form\">فارم کے لیے AVIF بدلنا</h2>\n<p>اپ لوڈ فارم قبول شدہ فارمیٹ کے طور پر JPG اور PNG لکھتے ہیں، اور AVIF فائل سیدھا واپس آ جاتی ہے۔ اپ لوڈ سے پہلے JPG میں بدلیں، اور پہلے فارم کے اصول جانچیں۔</p>\n<p>تصویر کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ تصویر صاف لگتی ہے، فائل معقول سائز کی ہوتی ہے اور فارم اسے بغیر کسی مشکل کے قبول کر لیتا ہے۔</p>\n<p>بدلنے کے بعد فائل سائز حد جانچیں۔ 2 MB تک اپ لوڈ دینے والا فارم 4 MB JPG مسترد کر سکتا ہے، اور آپ کو 100KB یا 200KB ٹول سے کمپریس کرنا پڑ سکتا ہے۔</p>\n<h2 id=\"avif-for-email\">ای میل کے لیے AVIF بدلنا</h2>\n<p>ای میل کلائنٹ JPG قابل اعتماد انداز میں دکھاتے ہیں، جبکہ AVIF سپورٹ متضاد ہے۔ AVIF منسلکہ ٹوٹی تصویر کے طور پر دکھائی دے سکتا ہے، جو کاروباری ای میل میں غیر پیشہ ورانہ لگتا ہے۔</p>\n<p>منسلک کرنے سے پہلے AVIF کو JPG میں بدلیں۔ JPG ہر ای میل کلائنٹ میں، ہر آلے پر درست دکھائی دیتا ہے، اور پیغام سالم پہنچتا ہے۔</p>\n<p>ای میل تصویروں کے لیے کوالٹی 85 فیصد پر رکھیں۔ تصویر صاف لگتی ہے، فائل بھیجنے کے لیے کافی چھوٹی ہوتی ہے اور وصول کنندہ وہی تصویر دیکھتا ہے جو آپ دیکھتے ہیں۔</p>\n<h2 id=\"avif-for-presentation\">پریزنٹیشن کے لیے AVIF بدلنا</h2>\n<p>پریزنٹیشن سلائیڈوں کو ایسی تصویریں چاہییں جو پریزنٹیشن کمپیوٹر پر کھلیں، اور پرانی مشین پر AVIF ناکام ہو سکتی ہے۔ پہلے JPG میں بدلیں، اور سلائیڈیں ہر جگہ کام کرتی ہیں۔</p>\n<p>سلائیڈوں میں شامل کرنے سے پہلے AVIF تصویروں کو 85 سے 90 فیصد کوالٹی پر JPG میں بدلیں۔ JPG ہر پاورپوائنٹ نسخے میں صاف ایمبیڈ ہوتی ہیں۔</p>\n<p>کئی تصویروں والے ڈیک کے لیے پورا سیٹ ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور JPG سلائیڈوں میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<h2 id=\"avif-for-client\">کلائنٹ کے لیے AVIF بدلنا</h2>\n<p>کلائنٹ کو اکثر ویب سائٹ سے AVIF فائلیں ملتی ہیں اور وہ انہیں کھول نہیں سکتے۔ فائلوں کو JPG میں بدلنے سے انہیں ایسی تصویریں ملتی ہیں جو ان کی ہر ایپ میں کام کرتی ہیں۔</p>\n<p>بدلنے سے پہلے کلائنٹ سے پوچھیں کہ انہیں تصویریں کس لیے چاہییں۔ ویب سائٹ کے لیے انہیں WebP چاہیے، جبکہ دستاویز کے لیے JPG چاہیے۔</p>\n<p>شک ہو تو دونوں فارمیٹ دیں۔ JPG فائلیں ہر جگہ کام کرتی ہیں، جبکہ AVIF اصل ویب کے لیے چھوٹی رہتی ہیں، اور کلائنٹ ہر استعمال کے حساب سے چن سکتا ہے۔</p>\n<h2 id=\"avif-on-old-computer\">پرانے کمپیوٹر پر AVIF بدلنا</h2>\n<p>پرانا کمپیوٹر AVIF بالکل ڈی کوڈ نہیں کر سکتا، کیونکہ اس فارمیٹ کو حالیہ براؤزر چاہیے ہوتا ہے۔ پہلے براؤزر اپ ڈیٹ کریں، اور تبدیلی کام کرنی چاہیے۔</p>\n<p>اگر براؤزر اپ ڈیٹ نہیں ہو سکتا تو AVIF فائلیں نئے آلے پر منتقل کریں اور وہاں بدلیں۔ فون یا نیا لیپ ٹاپ ڈی کوڈنگ بغیر مشکل کے سنبھال لیتا ہے۔</p>\n<p>ایک تصویر کے لیے نئے آلے پر آن لائن کنورٹر تیز ترین راستہ ہے۔ اسے بدلیں، JPG ڈاؤن لوڈ کریں اور JPG واپس پرانے کمپیوٹر پر منتقل کریں۔</p>\n<h2 id=\"avif-for-portfolio\">پورٹ فولیو کے لیے AVIF بدلنا</h2>\n<p>پورٹ فولیو کو بہترین دکھنا ہوتا ہے، اور تبدیلی کی ترتیبات کو یہی ظاہر کرنا چاہیے۔ AVIF تصویروں کو 90 فیصد کوالٹی پر JPG میں بدلیں، تاکہ کلائنٹ زوم کرے تب بھی تصویریں تیز رہیں۔</p>\n<p>پہلے مضبوط ترین تصویریں چنیں، پھر انہیں اہمیت کے حساب سے بدلیں۔ ہیرو تصویر سب سے زیادہ احتیاط کی مستحق ہے، کیونکہ یہ پورے پورٹ فولیو کا تاثر طے کرتی ہے۔</p>\n<p>بدلنے کے بعد ہر تصویر جانچیں، صرف نمونہ نہیں۔ پورٹ فولیو میں تصویریں کم ہوتی ہیں، اور ہر ایک اہم ہوتی ہے، اس لیے ان سب کا فوری جائزہ وقت کے قابل ہے۔</p>\n<p>پورا طریقہ یہی ہے: اپ لوڈ کریں، میٹ چنیں، کوالٹی طے کریں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/avif-ko-jpg-rehnumai/\">AVIF to JPG: Complete Guide</a> پڑھیں، اور آمنے سامنے موازنے کے لیے <a href=\"/ur/blog/avif-vs-jpg/\">AVIF vs JPG: Next-Gen Format vs Universal Format</a> دیکھیں۔ اگر آپ کو شفافیت رکھنی ہو تو <a href=\"/ur/tasveer-convert-karein/\">Image Converter</a> AVIF کو PNG میں بدل سکتا ہے۔</p>\n";

